function commitHistory(){clearTimeout(historyTimer);historyTimer=null;if(historyRestoring||batchRendering)return;const state=snapshot();if(sameSnapshot(state,historyEntries[historyIndex])){updateHistoryButtons();return}historyEntries=historyEntries.slice(0,historyIndex+1);historyEntries.push(state);if(historyEntries.length>50)historyEntries.shift();historyIndex=historyEntries.length-1;updateHistoryButtons()}
