$('undo').onclick=()=>moveHistory(-1);$('redo').onclick=()=>moveHistory(1);document.addEventListener('keydown',e=>{const focused=document.activeElement;if(focused&&['INPUT','TEXTAREA'].includes(focused.tagName)&&!fields.includes(focused.id))return;if(!(e.ctrlKey||e.metaKey)||e.altKey||e.key.toLowerCase()!=='z')return;if(batchRendering)return;e.preventDefault();moveHistory(e.shiftKey?1:-1)});
