refreshLibrary=async function(){const items=await allLibraryItems();libraryRecords=items.filter(r=>r?.kind==='saved-project').sort((a,b)=>b.updated-a.updated);libraryFolders=items.filter(r=>r?.kind==='saved-folder').sort((a,b)=>a.name.localeCompare(b.name,'pt-BR'));const validIds=new Set(libraryRecords.map(r=>r.id));selectedLibraryIds=new Set([...selectedLibraryIds].filter(id=>validIds.has(id)));for(const id of ['projectFolder','libraryFolderFilter','moveDestination'])fillFolderSelect($(id),id==='libraryFolderFilter');renderLibraryList()};
async function createLibraryFolder(){if(libraryBusy)return;const name=$('libraryFolderName').value.trim();if(!name){$('libraryStatus').textContent='Digite o nome da pasta.';return}if(name.length>80){$('libraryStatus').textContent='Use até 80 caracteres no nome da pasta.';return}if(libraryFolders.some(f=>libraryKey(f.name)===libraryKey(name))){$('libraryStatus').textContent='Já existe uma pasta com esse nome.';return}try{const id='folder:'+crypto.randomUUID();await libraryWrite({kind:'saved-folder',id,name,created:Date.now()});await refreshLibrary();$('projectFolder').value=id;$('libraryFolderFilter').value=id;$('libraryFolderName').value='';renderLibraryList();$('libraryStatus').textContent='Pasta criada: '+name}catch(e){$('libraryStatus').textContent=e.message}}
async function renameLibraryFolder(){if(libraryBusy)return;const folder=libraryFolders.find(f=>f.id===$('libraryFolderFilter').value),name=$('libraryFolderName').value.trim();if(!folder)return;if(!name||name.length>80){$('libraryStatus').textContent='Digite um novo nome de até 80 caracteres.';return}if(libraryFolders.some(f=>f.id!==folder.id&&libraryKey(f.name)===libraryKey(name))){$('libraryStatus').textContent='Já existe uma pasta com esse nome.';return}try{await libraryWrite({...folder,name});await refreshLibrary();$('libraryFolderName').value='';$('libraryStatus').textContent='Pasta renomeada.'}catch(e){$('libraryStatus').textContent=e.message}}
async function deleteLibraryFolder(){if(libraryBusy)return;const folder=libraryFolders.find(f=>f.id===$('libraryFolderFilter').value);if(!folder||!confirm('Excluir a pasta "'+folder.name+'"? Os projetos serão movidos para Sem pasta.'))return;try{const moves=libraryRecords.filter(r=>r.folderId===folder.id).map(r=>({...r,folderId:'',updated:Date.now()}));await libraryBatchWrite(moves,[folder.id]);await refreshLibrary();$('libraryStatus').textContent='Pasta excluída. Seus projetos foram preservados.'}catch(e){$('libraryStatus').textContent=e.message}}
async function moveLibrarySelection(){if(libraryBusy)return;const destination=$('moveDestination').value,records=libraryRecords.filter(r=>selectedLibraryIds.has(r.id)).map(r=>({...r,folderId:destination,updated:Date.now()}));if(!records.length)return;try{await libraryBatchWrite(records);await refreshLibrary();$('libraryStatus').textContent=records.length+' projetos movidos para '+libraryFolderName(destination)+'.'}catch(e){$('libraryStatus').textContent=e.message}}
saveInLibrary=async function(copy=false){if(libraryBusy)return;const button=copy?$('saveCopy'):$('storeProject');button.disabled=true;try{await embeddedReady;if(!await fontsReady)throw new Error('Aguarde as fontes carregarem.');await ensureFrameAsset();const project=await portableSnapshot(),name=($('libraryName').value.trim()||$('name').value||'Minha carta').slice(0,160),id=!copy&&activeProjectId?activeProjectId:'saved:'+crypto.randomUUID(),old=libraryRecords.find(r=>r.id===id);const record={kind:'saved-project',id,name,folderId:$('projectFolder').value,updated:Date.now(),created:old?.created||Date.now(),project,thumbnail:projectThumbnail()};await libraryWrite(record);activeProjectId=id;await refreshLibrary();$('libraryStatus').textContent='Projeto guardado: '+name+'.';message('Projeto guardado na biblioteca deste navegador.')}catch(e){$('libraryStatus').textContent='Não foi possível salvar: '+e.message;message(e.message,true)}finally{button.disabled=false}};
$('libraryBtn').onclick=async()=>{$('libraryDialog').showModal();try{await refreshLibrary();const active=libraryRecords.find(r=>r.id===activeProjectId);$('libraryName').value=active?.name||$('name').value;$('projectFolder').value=active?.folderId||'';$('libraryStatus').textContent=libraryRecords.length+' projetos guardados.'}catch{$('libraryStatus').textContent='A biblioteca local não está disponível neste navegador.'}};
$('librarySearch').addEventListener('input',renderLibraryList);$('libraryFolderFilter').onchange=renderLibraryList;$('createLibraryFolder').onclick=createLibraryFolder;$('renameLibraryFolder').onclick=renameLibraryFolder;$('deleteLibraryFolder').onclick=deleteLibraryFolder;$('moveSelected').onclick=moveLibrarySelection;$('selectVisibleLibrary').onclick=()=>{for(const r of libraryVisibleRecords())selectedLibraryIds.add(r.id);renderLibraryList()};$('clearLibrarySelection').onclick=()=>{selectedLibraryIds.clear();renderLibraryList()};
function makeLibraryBackup(records,folders){return{format:'arcana-library',version:1,createdAt:new Date().toISOString(),folders:folders.map(f=>({id:f.id,name:f.name})),projects:records.map(r=>({id:r.id,name:r.name,folderId:r.folderId||'',created:r.created,updated:r.updated,project:r.project,thumbnail:r.thumbnail}))}}
async function exportLibraryBackup(selected=false){try{await refreshLibrary();const records=selected?libraryRecords.filter(r=>selectedLibraryIds.has(r.id)):libraryRecords;if(selected&&!records.length)throw new Error('Selecione ao menos um projeto.');const used=new Set(records.map(r=>r.folderId)),folders=selected?libraryFolders.filter(f=>used.has(f.id)):libraryFolders;if(!records.length&&!folders.length)throw new Error('A biblioteca está vazia.');const backup=validateLibraryBackup(makeLibraryBackup(records,folders)),backupBlob=new Blob([JSON.stringify(backup)],{type:'application/json'});if(backupBlob.size>150000000)throw new Error('O backup excede 150 MB. Selecione menos projetos ou reduza suas imagens.');saveBlob(backupBlob,'Arcana_biblioteca_'+new Date().toISOString().slice(0,10)+'.arcana-library.json');$('libraryStatus').textContent='Backup baixado: '+records.length+' projetos e '+folders.length+' pastas.'}catch(e){$('libraryStatus').textContent=e.message}}
function backupObject(value){return !!value&&typeof value==='object'&&!Array.isArray(value)}
function validateBackupProject(p){if(!backupObject(p)||p.format!=='arcana-studio'||p.version!==2||!backupObject(p.values)||!backupObject(p.media))throw new Error('O backup contém um projeto inválido.');for(const[k,v]of Object.entries(p.values)){if(!fields.includes(k))continue;if(!['string','number','boolean'].includes(typeof v)||String(v).length>100000)throw new Error('Há um campo inválido no backup.')}for(const kind of mediaKinds){const url=p.media[kind]??'';if(typeof url!=='string'||url.length>36000000||url&&!/^(data:image\/(png|jpeg|webp|gif|svg\+xml);base64,|https:\/\/(cards|svgs)\.scryfall\.io\/)/.test(url))throw new Error('Há uma imagem inválida no backup.')}if(p.fonts!==undefined&&!backupObject(p.fonts))throw new Error('Fontes inválidas no backup.');for(const kind of ['title','rules']){const url=p.fonts?.[kind]??'';if(typeof url!=='string'||url.length>7200000||url&&!/^data:application\/octet-stream;base64,/.test(url))throw new Error('Há uma fonte inválida no backup.')}return p}
function validateLibraryBackup(data){if(!backupObject(data)||data.format!=='arcana-library'||data.version!==1||!Array.isArray(data.projects)||!Array.isArray(data.folders)||data.projects.length>500||data.folders.length>200)throw new Error('Este arquivo não é um backup válido da biblioteca Arcana.');const ids=new Set();for(const f of data.folders){if(!backupObject(f)||typeof f.id!=='string'||!f.id||ids.has(f.id)||typeof f.name!=='string'||!f.name.trim()||f.name.length>80)throw new Error('Há uma pasta inválida no backup.');ids.add(f.id)}const projects=new Set();for(const r of data.projects){if(!backupObject(r)||typeof r.id!=='string'||!r.id||projects.has(r.id)||typeof r.name!=='string'||!r.name.trim()||r.name.length>160||r.folderId&&!ids.has(r.folderId))throw new Error('Há um registro inválido no backup.');projects.add(r.id);validateBackupProject(r.project);if(r.thumbnail!==undefined&&(typeof r.thumbnail!=='string'||r.thumbnail.length>2000000||r.thumbnail&&!/^data:image\/(png|jpeg|webp|svg\+xml);base64,/.test(r.thumbnail)))throw new Error('Há uma miniatura inválida no backup.')}if(!data.projects.length&&!data.folders.length)throw new Error('O backup está vazio.');return data}
async function prepareLibraryBackup(file){pendingLibraryBackup=null;$('confirmRestoreLibrary').disabled=true;$('libraryRestoreSummary').hidden=true;if(!file)return;try{if(file.size>150000000)throw new Error('Use um backup de até 150 MB.');const data=validateLibraryBackup(JSON.parse(await file.text()));pendingLibraryBackup=data;$('libraryRestoreText').textContent=data.projects.length+' projetos e '+data.folders.length+' pastas serão adicionados. Projetos existentes serão preservados; os importados serão novas cópias.';$('libraryRestoreSummary').hidden=false;$('confirmRestoreLibrary').disabled=false;$('libraryStatus').textContent='Backup verificado. Confira o resumo antes de restaurar.'}catch(e){$('libraryStatus').textContent='Não foi possível abrir o backup: '+e.message}}
async function restoreLibraryBackup(){if(!pendingLibraryBackup||libraryBusy)return;libraryBusy=true;$('confirmRestoreLibrary').disabled=true;try{const data=validateLibraryBackup(pendingLibraryBackup);await refreshLibrary();const records=[],folderMap=new Map(),known=[...libraryFolders];for(const folder of data.folders){let match=known.find(f=>libraryKey(f.name)===libraryKey(folder.name));if(!match){match={kind:'saved-folder',id:'folder:'+crypto.randomUUID(),name:folder.name.trim(),created:Date.now()};known.push(match);records.push(match)}folderMap.set(folder.id,match.id)}const thumbnail=frameCatalog.find(p=>p.id==='modern').thumb;for(const source of data.projects){records.push({kind:'saved-project',id:'saved:'+crypto.randomUUID(),name:source.name.trim(),folderId:folderMap.get(source.folderId)||'',created:Number.isFinite(source.created)?source.created:Date.now(),updated:Date.now(),project:source.project,thumbnail:source.thumbnail||thumbnail})}await libraryBatchWrite(records);pendingLibraryBackup=null;$('libraryBackupFile').value='';$('libraryRestoreSummary').hidden=true;await refreshLibrary();$('libraryStatus').textContent='Backup restaurado: '+data.projects.length+' projetos adicionados como cópias.'}catch(e){$('libraryStatus').textContent='A restauração não foi concluída: '+e.message;$('confirmRestoreLibrary').disabled=false}finally{libraryBusy=false;updateLibrarySelection()}}
$('backupAll').onclick=()=>exportLibraryBackup(false);$('backupSelected').onclick=()=>exportLibraryBackup(true);$('restoreLibraryBtn').onclick=()=>$('libraryBackupFile').click();$('libraryBackupFile').addEventListener('change',e=>prepareLibraryBackup(e.target.files?.[0]));$('confirmRestoreLibrary').onclick=restoreLibraryBackup;$('cancelRestoreLibrary').onclick=()=>{pendingLibraryBackup=null;$('libraryRestoreSummary').hidden=true;$('libraryBackupFile').value=''};

async function fetchWithTimeout(url,options={}){const controller=new AbortController(),external=options.signal,abort=()=>controller.abort();if(external?.aborted)controller.abort();else external?.addEventListener('abort',abort,{once:true});let timedOut=false;const timer=setTimeout(()=>{timedOut=true;controller.abort()},20000);try{return await fetch(url,{...options,signal:controller.signal})}catch(error){if(timedOut)throw new Error('A consulta demorou demais. Verifique a conexão e tente novamente.');throw error}finally{clearTimeout(timer);external?.removeEventListener('abort',abort)}}
