imageUrl=function(url){return new Promise((resolve,reject)=>{const img=new Image();let timer;const done=(error)=>{clearTimeout(timer);img.onload=null;img.onerror=null;if(error)reject(error);else if(!img.width||!img.height)reject(new Error('A imagem não possui dimensões válidas.'));else resolve(img)};img.crossOrigin='anonymous';img.onload=()=>done();img.onerror=()=>done(new Error('Não foi possível carregar a imagem.'));timer=setTimeout(()=>done(new Error('A imagem demorou demais para carregar. Tente novamente.')),30000);img.src=url})};
