function normalizedProject(project){validateBackupProject(project);const values={...fieldDefaults};const enums={frame:frameCatalog.map(p=>p.id),palette:['artifact','white','blue','black','red','green','gold','land','custom'],rarity:['common','uncommon','rare','mythic'],cardLayout:['normal','planeswalker','saga','adventure','split'],colorBlend:['smooth','split'],textAlign:['left','center','right']};for(const id of fields){if(!(id in project.values))continue;const value=project.values[id];if(enums[id]&&!enums[id].includes(value))throw new Error('Opção inválida no campo '+id+'.');if($(id).type==='checkbox'){if(typeof value!=='boolean')throw new Error('Opção inválida no campo '+id+'.');values[id]=value}else if($(id).type==='range'||$(id).type==='number'){const n=Number(value);if(!Number.isFinite(n))throw new Error('Número inválido no campo '+id+'.');const min=Number($(id).min),max=Number($(id).max);values[id]=String(Math.min($(id).max!==undefined&&$(id).max!==''?max:Infinity,Math.max($(id).min!==undefined&&$(id).min!==''?min:-Infinity,n)))}else{if(!['string','number'].includes(typeof value))throw new Error('Texto inválido no campo '+id+'.');values[id]=String(value)}}return{...project,values,media:Object.fromEntries(mediaKinds.map(k=>[k,project.media[k]||''])),fonts:project.fonts||{}}}
